//! Identity of a loaded rule or virtual device.

use std::fmt::Display;

use config_watcher::ConfigItemHash;

/// Key of a rule or virtual device: the hash of its config file plus a hash of the item.
///
/// Items read from a config document keep the watcher's [`ConfigItemHash`]; items generated by
/// template expansion use the source file's hash and a hash of the expanded document, so an
/// unchanged expansion result keeps its key (and its timers) across re-expansions.
#[derive(Debug, Clone, Copy, Eq, Hash, PartialEq, PartialOrd, Ord)]
pub struct ItemHash {
    file: u64,
    item: u64,
}

impl ItemHash {
    pub fn new(filename_hash: u64, item_hash: u64) -> Self {
        Self {
            file: filename_hash,
            item: item_hash,
        }
    }

    pub fn filename_hash(&self) -> u64 {
        self.file
    }

    pub fn item_hash(&self) -> u64 {
        self.item
    }
}

impl From<ConfigItemHash> for ItemHash {
    fn from(hash: ConfigItemHash) -> Self {
        Self::new(hash.filename_hash(), hash.item_hash())
    }
}

impl Display for ItemHash {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}-{}", self.file, self.item)
    }
}
